function checkNudges(){if(!('Notification'in window)||Notification.permission!=='granted')return;const now=Date.now();const t=state.tasks.filter(t=>!t.done&&!t.demo&&t.next<=now&&!t.notified).sort((a,b)=>a.next-b.next)[0];if(!t)return;try{const n=new Notification('A little nudge',{body:t.title,tag:t.id,icon:'icon.svg'});n.onclick=()=>{window.focus();navigate('reminders');n.close();};t.notified=now;save();}catch{/* Some mobile browsers require the native build for scheduled notifications. */}}
