async function loadOwl(retry=false){const show=()=>document.querySelectorAll('.owl-test').forEach(b=>{const img=b.querySelector('img');img.onload=()=>b.classList.add('owl-ready');img.onerror=()=>{b.classList.remove('owl-ready');b.querySelector('span').textContent='Retry';};if(owlPng){img.src=owlPng;if(img.complete&&img.naturalWidth)b.classList.add('owl-ready');}});if(owlPng){show();return;}if(owlLoading&&!retry){await owlLoading;show();return;}owlLoading=(async()=>{try{const r=await fetch('./manifest.webmanifest',{cache:'no-cache'});if(!r.ok)throw Error();const data=await r.json();if(typeof data.nudgePreviewOwl!=='string'||!data.nudgePreviewOwl.startsWith('data:image/png;base64,'))throw Error();owlPng=data.nudgePreviewOwl;owlLogoOptions=Array.isArray(data.nudgePreviewLogos)?data.nudgePreviewLogos:[];updateOwlBrand();show();}catch{document.querySelectorAll('.owl-loading').forEach(el=>el.textContent='Retry');}finally{owlLoading=null;}})();await owlLoading;}
