function reminderDesignPage(){const done=reminderDesignTasks.filter(t=>t.done).length;main.innerHTML=`<button class="back-button" data-page="home">← Back to Today</button><div class="design-title-row"><div><h1>Small, gentle nudges</h1><p>Try each at your phone’s actual width.</p></div>${owlMarkup()}</div><div class="design-switcher" role="group" aria-label="Reminder styles">${reminderDesignNames.map((name,i)=>`<button data-action="design-style" data-style="${i+1}" aria-pressed="${reminderDesign===i+1}" aria-label="Style ${i+1}: ${name}">${i+1}</button>`).join('')}</div><div class="design-current"><strong>${reminderDesign}. ${reminderDesignNames[reminderDesign-1]}</strong><span>Sample reminders</span></div><div class="mini-list mini-style-${reminderDesign}">${reminderDesignTasks.map(compactSampleCard).join('')}</div><p class="design-help">Tap a title to edit, a circle to tick, or Later to try snoozing. Your real reminders stay as they are.</p><div class="design-bottom"><span role="status">${done?done+' of 4 ticked off':'Four reminders, one small space'}</span><button data-action="design-reset">Reset samples</button></div>`;loadOwl();}
